package vn.eventplatform.ad.domain;
import jakarta.persistence.*; import lombok.*; import vn.eventplatform.ad.enums.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="ad_campaigns") @Getter @Setter @NoArgsConstructor public class AdCampaign extends BaseEntity { @Column(name="organizer_id",nullable=false) private UUID organizerId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="package_id",nullable=false) private AdPackage adPackage; @Column(nullable=false) private String name; @Enumerated(EnumType.STRING) @Column(name="pricing_mode",nullable=false) private PricingMode pricingMode; @Enumerated(EnumType.STRING) @Column(nullable=false) private CampaignStatus status=CampaignStatus.PENDING_APPROVAL; private String rejectionReason; @Column(nullable=false) private BigDecimal feeAmount=BigDecimal.ZERO; @Column(nullable=false) private BigDecimal escrowAmount=BigDecimal.ZERO; @Column(nullable=false) private Boolean settlementPublished=false; @Column(name="starts_at",nullable=false) private LocalDateTime startsAt; @Column(name="ends_at",nullable=false) private LocalDateTime endsAt; }
